const $ = s => document.querySelector(s);
const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
const fmt = (n,d=0) => Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const today = new Date();
const dateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
// Empty public demo: no personal measurements or preloaded health records.
const baseMeals = [];
let state = {water:0,waterGoal:2000,calorieGoal:2100,goalWeight:75,meals:[],habits:[false,false,false,false],weights:[],exercises:[],workoutStarted:false,workoutDone:false};
const initialState=structuredClone(state);
let saveOnDevice=false;

let view='hoje',nutritionTab='diary';
const escapeHtml = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={hoje:'Hoje',treino:'Treino',alimentacao:'Comida',evolucao:'Peso',lembretes:'Lembretes',conta:'Mais'};
function totals(){return state.meals.reduce((a,m)=>({kcal:a.kcal+m.kcal,p:a.p+m.p,c:a.c+m.c,f:a.f+m.f}),{kcal:0,p:0,c:0,f:0});}
function welcome(eyebrow,title,subtitle){return `<div class="welcome"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="date-control" title="${today.toLocaleDateString('pt-BR',{dateStyle:'full'})}">${icon('calendar-days')}${today.toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span></div>`;}
function weekStrip(){const weekday=(today.getDay()+6)%7;return `<div class="week-strip"><div class="week-intro"><span>${icon('calendar-check-2')}</span><div><strong>Uma semana de cuidado</strong><small>Hoje é um bom dia para continuar.</small></div></div><div class="week-days">${['S','T','Q','Q','S','S','D'].map((day,i)=>{const d=new Date(today);d.setDate(today.getDate()+i-weekday);return `<div class="week-day ${i===weekday?'today':''}" ${i===weekday?'aria-current="date"':''}><span>${d.getDate()}</span>${day}</div>`}).join('')}</div></div>`;}
function nutritionCard(){const t=totals(),left=Math.max(0,state.calorieGoal-t.kcal),percent=Math.min(t.kcal/state.calorieGoal,1);return `<section class="card nutrition-card"><div class="card-title"><div class="title-with-icon">${icon('flame')}<h2>Seu equilíbrio hoje</h2></div><span class="tag">Calorias</span></div><div class="nutrition-overview"><div class="calorie-ring" role="img" aria-label="${fmt(t.kcal)} de ${fmt(state.calorieGoal)} quilocalorias registradas"><svg viewBox="0 0 180 180" aria-hidden="true"><circle class="ring-track" cx="90" cy="90" r="76"/><circle class="ring-fill" cx="90" cy="90" r="76" stroke-dasharray="477.5" stroke-dashoffset="${477.5*(1-percent)}"/></svg><div class="ring-center">${icon('flame')}<strong>${fmt(left)}</strong><span>${t.kcal>state.calorieGoal?'meta alcançada':'kcal restantes'}</span></div></div><div class="calorie-detail"><div class="calorie-summary"><div><span>Consumidas</span><strong>${fmt(t.kcal)} <small>kcal</small></strong></div><div><span>Meta diária</span><strong>${fmt(state.calorieGoal)} <small>kcal</small></strong></div></div><div class="macros">${[['Proteínas',t.p,'#b8d893'],['Carboidratos',t.c,'#eccb8f'],['Gorduras',t.f,'#b8bfdc']].map(([label,value,color])=>`<div class="macro-row"><span>${label}</span><div class="bar"><span style="width:${Math.min(100,value*(label==='Gorduras'?9:4)/state.calorieGoal*100)}%;background:${color}"></span></div><span>${fmt(value)} g</span></div>`).join('')}</div></div></div><div class="nutrition-footer"><span>${icon('info')}${state.personalPlan?'Meta pessoal provisória':'Meta ilustrativa e ajustável'}</span><button data-action="meal">+ Registrar refeição</button></div></section>`;}
function waterCard(){return `<section class="card water-card"><div class="card-title"><div class="title-with-icon">${icon('droplet')}<h2>Um gole de cuidado</h2></div><span class="tag">Água</span></div><div class="water-stats"><strong>${fmt(state.water/1000,2)} <span>L</span></strong><span>/ ${fmt(state.waterGoal/1000,1)} L</span></div><p>${state.water>=state.waterGoal?'Meta de água alcançada.':'Ao longo do dia, no seu ritmo.'}</p><div class="water-glasses" aria-label="${state.water} de ${state.waterGoal} mililitros">${Array.from({length:8},(_,i)=>`<span class="water-glass ${i<Math.floor(state.water/state.waterGoal*8)?'filled':''}">${icon('droplet')}</span>`).join('')}</div><button data-action="water" class="water-add">${icon('plus')}<span>250 ml de água</span></button></section>`;}
function workoutCard(){if(state.personalPlan)return window.OasisUI?.workoutPlan?.()||'';return `<section class="card workout-card"><div class="workout-top"><span class="workout-label">${icon('dumbbell')}SEU TREINO DE HOJE</span><span class="workout-type">Treino A</span></div><div class="workout-mark">${icon('dumbbell')}</div><h2>Treino A · Superiores</h2><p>Peito, ombros e tríceps</p><div class="workout-meta"><span>${icon('clock-3')}45–55 min</span><span>${icon('layers')}6 exercícios</span></div><div class="workout-bottom"><div class="muscle-tags"><span>Força</span><span>Superiores</span></div><button class="primary-button" ${view==='treino'?'data-action="'+(state.workoutStarted?'scroll-exercises':'start-workout')+'"':'data-view="treino"'}>${icon(state.workoutDone?'check':state.workoutStarted?'arrow-right':'play')}${state.workoutDone?'Treino concluído':state.workoutStarted?'Continuar treino':view==='treino'?'Iniciar sessão':'Ver meu treino'}</button></div></section>`;}
const habitNames=['Registrar alimentação','Beber água','Fazer meu treino','Preparar o sono'];
function habitCard(){return `<section class="card habit-card"><div class="card-title"><h2>Pequenos hábitos</h2><small>${state.habits.filter(Boolean).length} de 4 feitos</small></div><div class="habit-list">${habitNames.map((name,i)=>`<button class="habit-button ${state.habits[i]?'checked':''}" data-habit="${i}" aria-pressed="${state.habits[i]}"><span class="check-box">${icon('check')}</span><span class="habit-text">${i===2&&state.personalPlan?'Respeitar minha recuperação':name}</span>${icon(['utensils','droplet','dumbbell','moon'][i])}</button>`).join('')}</div></section>`;}
function chart(){const w=state.weights.slice(-7);const values=w.map(x=>x.value);const lo=Math.min(...values)-.5,hi=Math.max(...values)+.5;const pts=w.map((x,i)=>[12+i*476/Math.max(w.length-1,1),82-(x.value-lo)/(hi-lo)*63]);const path=pts.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');return `<svg class="weight-chart" viewBox="0 0 500 105" role="img" aria-label="Evolução do peso de ${fmt(values[0],1)} para ${fmt(values.at(-1),1)} quilogramas"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d9eac5" stop-opacity=".6"/><stop offset="1" stop-color="#f8fbf3" stop-opacity=".1"/></linearGradient></defs><path class="chart-grid" d="M0 30H500 M0 65H500 M0 100H500"/><path d="${path} L${pts.at(-1)[0]},100 L12,100Z" fill="url(#chart-fill)"/><path d="${path}" stroke="#93b576" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i===pts.length-1?4.5:3}" fill="${i===pts.length-1?'#759b57':'white'}" stroke="#93b576" stroke-width="2"/>`).join('')}</svg><div class="chart-labels">${w.map(x=>`<span>${new Date(x.date+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace(' de ',' ').replace('.','')}</span>`).join('')}</div>`;}
function weightCard(big=false){if(!state.weights.length)return `<section class="card"><h2>Sua história começa aqui</h2><p class="muted section-copy">Registre seu peso para acompanhar sua evolução ao longo do tempo.</p><button class="primary-button" data-action="weight">${icon('plus')}Registrar peso</button></section>`;const current=state.weights.at(-1).value,delta=current-state.weights[0].value;return `<section class="card ${big?'weight-big-chart':''}"><div class="card-title"><div class="title-with-icon">${icon('chart-no-axes-combined')}<h2>Cada passo conta</h2></div><button class="link-button" data-view="evolucao">Ver evolução ${icon('arrow-up-right')}</button></div><div class="weight-top"><div class="weight-value"><strong>${fmt(current,1)}</strong><span>kg</span><p>Último peso registrado</p></div><span class="weight-change">${icon(delta<=0?'trending-down':'trending-up')}${delta>0?'+':''}${fmt(delta,1)} kg no período</span></div>${chart()}</section>`;}
function nextMeal(){return `<section class="card"><div class="card-title"><h2>Próxima pausa</h2><span class="tag">Exemplo de refeição</span></div><div class="meal-preview"><span class="meal-icon">${icon('soup')}</span><div class="meal-info"><h3>Jantar</h3><p>Uma pausa para comer com calma.</p></div><span class="meal-time">19:30</span></div><div class="next-meal-macros"><div><strong>${fmt(state.meals.length)}</strong>refeições registradas</div><div><strong>${fmt(totals().kcal)}</strong>kcal ao longo do dia</div></div><button class="secondary-button full-width" data-view="alimentacao">Meu diário alimentar ${icon('arrow-right')}</button></section>`;}
function home(){const weight=state.weights.at(-1);return `${simpleHeading('Hoje',new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}))}<div class="simple-home"><section class="card simple-calories"><div class="card-title"><h2>Calorias de hoje</h2><button class="link-button" data-view="alimentacao">Ver alimentos ${icon('chevron-right')}</button></div>${calorieSummary()}<button class="primary-button full-width simple-main-action" data-action="meal">${icon('plus')}Registrar comida</button></section><div class="simple-pair"><section class="card simple-stat"><span class="simple-stat-label">${icon('droplet')}Água de hoje</span><strong>${fmt(state.water)} <small>ml</small></strong><p>Meta: ${fmt(state.waterGoal)} ml</p><button class="secondary-button full-width" data-action="water">${icon('plus')}250 ml de água</button></section><section class="card simple-stat"><span class="simple-stat-label">${icon('weight')}Último peso</span><strong>${weight?fmt(weight.value,1):'—'} <small>kg</small></strong><p>${weight?new Date(weight.date+'T12:00:00').toLocaleDateString('pt-BR'):'Nenhum registro'}</p><button class="secondary-button full-width" data-action="weight">${icon('plus')}Registrar peso</button></section></div><section class="card simple-training-link"><span class="simple-stat-label">${icon('dumbbell')}Treino</span><div><h2>${state.personalPlan?'Aguardando avaliação':state.workoutDone?'Concluído hoje':'Ver meu treino'}</h2><p>${state.personalPlan?'Confira os dias reservados e as orientações.':state.workoutDone?'Sua sessão foi registrada.':'Confira os exercícios antes de iniciar.'}</p></div><button class="secondary-button" data-view="treino">Abrir treino ${icon('chevron-right')}</button></section><details class="simple-details"><summary>Hábitos do dia</summary>${habitCard()}</details></div>`;}
function simpleHeading(title,subtitle='',actionMarkup=''){return `<div class="simple-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${actionMarkup}</div>`;}
function calorieSummary(){const t=totals(),difference=state.calorieGoal-t.kcal,percent=Math.min(100,t.kcal/state.calorieGoal*100);return `<div class="simple-calorie-number"><strong>${fmt(t.kcal)}</strong><span>/ ${fmt(state.calorieGoal)} kcal</span></div><div class="bar simple-progress" role="progressbar" aria-label="Calorias registradas em relação à meta" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><span style="width:${percent}%"></span></div><p class="simple-calorie-caption">${difference>=0?`${fmt(difference)} kcal até a meta`:`${fmt(-difference)} kcal acima da meta`}</p>`;}
const exercises=[['Supino reto com halteres','3 séries · 10–12 repetições','Peito'],['Supino inclinado','3 séries · 10–12 repetições','Peito'],['Crucifixo na máquina','3 séries · 12 repetições','Peito'],['Desenvolvimento com halteres','3 séries · 10–12 repetições','Ombros'],['Elevação lateral','3 séries · 12–15 repetições','Ombros'],['Tríceps na polia','3 séries · 12 repetições','Tríceps']];
function training(){if(state.personalPlan)return window.OasisUI?.trainingPlan?.()||'';const done=state.exercises.length;return `${welcome('','Treino','Programa de exemplo. Confirme seu treino com o profissional.')}<div class="view-grid"><div class="stack">${workoutCard()}<section class="card"><div class="card-title"><h2>Exercícios</h2><span class="tag">${done} / 6 feitos</span></div><p class="muted section-copy">Marque cada exercício quando terminar.</p>${exercises.map((e,i)=>`<div class="exercise ${state.exercises.includes(i)?'complete':''}"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div><h3>${e[0]}</h3><p>${e[1]}</p></div><button class="icon-button" data-exercise="${i}" aria-label="${state.exercises.includes(i)?'Desmarcar':'Concluir'} ${e[0]}" aria-pressed="${state.exercises.includes(i)}" ${!state.workoutStarted?'disabled':''}>${icon(state.exercises.includes(i)?'check':'circle')}</button></div>`).join('')}<p class="inline-note">Treino ilustrativo para explorar o aplicativo. Seu programa, cargas e intervalos devem seguir a orientação do profissional que acompanha você.</p></section></div><div class="stack"><section class="card"><div class="title-with-icon">${icon('timer')}<h2>Sua sessão</h2></div><div class="detail-stat"><span>Tempo de sessão</span><strong id="session-time">${sessionTime()}</strong></div><div class="detail-stat"><span>Exercícios concluídos</span><strong>${done} de 6</strong></div><div class="workout-progress"><div class="bar" role="progressbar" aria-label="Progresso do treino" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="6"><span style="width:${done/6*100}%"></span></div><p class="muted">${state.workoutDone?'Você reservou um tempo para cuidar de si.':done===6?'Tudo marcado. Você pode finalizar sua sessão.':'Um exercício de cada vez.'}</p></div>${state.workoutDone?`<div class="inline-note">Treino concluído e hábito marcado no seu dia.</div>`:`<button class="primary-button full-width" data-action="${state.workoutStarted?'finish-workout':'start-workout'}" ${state.workoutStarted&&done<6?'disabled':''}>${icon(state.workoutStarted?'check':'play')}${state.workoutStarted?'Concluir treino':'Iniciar sessão'}</button>`}</section>${habitCard()}</div></div>`;}
function nutrition(){const t=totals(),hasPlan=!!state.personalPlan,showPlan=hasPlan&&nutritionTab==='plan';return `${simpleHeading('Comida','',`<button class="primary-button" data-action="meal">${icon('plus')}Registrar comida</button>`)}${hasPlan?`<div class="simple-tabs" role="group" aria-label="Visualizar alimentação"><button data-action="food-diary" aria-pressed="${!showPlan}" ${!showPlan?'class="selected"':''}>O que comi hoje</button><button data-action="food-plan" aria-pressed="${showPlan}" ${showPlan?'class="selected"':''}>Meu cardápio</button></div>`:''}${showPlan?window.OasisUI?.nutritionPlan?.()||'':`<section class="card simple-food-total">${calorieSummary()}<div class="simple-macros">${[['Proteínas',t.p],['Carboidratos',t.c],['Gorduras',t.f]].map(([name,value])=>`<span><strong>${fmt(value,1)} g</strong>${name}</span>`).join('')}</div></section><section class="card simple-diary"><h2>Alimentos registrados</h2>${state.meals.length?['Café da manhã','Almoço','Lanche da tarde','Jantar','Outra refeição'].map(type=>{const meals=state.meals.filter(m=>m.type===type);return meals.length?`<div class="simple-meal-group"><div class="simple-meal-heading"><h3>${type}</h3><span>${fmt(meals.reduce((n,m)=>n+m.kcal,0))} kcal</span></div>${meals.map(m=>`<div class="simple-food-row"><div><strong>${escapeHtml(m.name)}</strong><span>${fmt(m.kcal,1)} kcal</span></div><button class="icon-button" data-remove-meal="${m.id}" aria-label="Excluir ${escapeHtml(m.name)}">${icon('trash-2')}</button></div>`).join('')}</div>`:'';}).join(''):'<div class="simple-empty"><p>Nenhum alimento registrado hoje.</p><p>Toque em <strong>Registrar comida</strong>, escolha o alimento e informe os gramas.</p></div>'}</section><details class="simple-details"><summary>Meta de calorias e calculadora</summary><div class="simple-detail-actions"><button class="secondary-button" data-action="settings">Editar minhas metas</button><button class="secondary-button" data-action="calculator">Calcular pelos nutrientes</button></div></details>`}`;}
function evolution(){const weights=state.weights,current=weights.at(-1),pending=state.personalPlan?.weightGoalPending;return `${simpleHeading('Peso','',`<button class="primary-button" data-action="weight">${icon('plus')}Registrar peso</button>`)}<section class="card simple-weight"><span class="simple-stat-label">Último peso registrado</span><div class="simple-calorie-number"><strong>${current?fmt(current.value,1):'—'}</strong><span>kg</span></div>${current?`<p class="simple-calorie-caption">${new Date(current.date+'T12:00:00').toLocaleDateString('pt-BR')}</p>${weights.length>1?chart():''}`:'<p class="simple-calorie-caption">Adicione seu primeiro registro.</p>'}<div class="simple-weight-goal"><span>${pending?'Meta de peso não definida':`Meta: ${fmt(state.goalWeight,1)} kg`}</span><button class="link-button" data-action="settings">Editar metas</button></div></section><section class="card simple-weight-history"><h2>Histórico de peso</h2>${weights.length?[...weights].reverse().map(w=>`<div class="history-row"><span>${new Date(w.date+'T12:00:00').toLocaleDateString('pt-BR')}</span><strong>${fmt(w.value,1)} kg</strong></div>`).join(''):'<p class="simple-empty">Seus registros aparecerão aqui.</p>'}</section>`;}
function render(){const pages={hoje:home,treino:training,alimentacao:nutrition,evolucao:evolution,lembretes:()=>window.OasisUI?.reminders()||'',conta:()=>window.OasisUI?.account()||''};$('#main').innerHTML=`<div class="tab-content">${pages[view]()}</div>`;$('#page-name').textContent=names[view];document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===view||(view==='lembretes'&&el.dataset.view==='conta');el.classList.toggle('active',active);if(el.closest('nav')){if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');}});window.lucide?.createIcons();}
function persist(){if(document.body.classList.contains('signed-in'))return;if(saveOnDevice){try{localStorage.setItem('webfit-demo-v1',JSON.stringify({day:dateKey(new Date()),state}));}catch{saveOnDevice=false;toast('Não foi possível salvar neste dispositivo.');}}}
function update(message){render();if(window.oasisSave){window.oasisSave(structuredClone(state),message);}else{persist();if(message)toast(message);}}
let toastTimeout;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function navigate(next){if(!names[next])next='hoje';view=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});window.OasisUI?.onNavigate?.(next);}
function modal(title,description,body){$('#modal-body').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Fechar">${icon('x')}</button></div><p class="modal-description">${description}</p>${body}`;window.lucide?.createIcons();if(!$('#modal').open)$('#modal').showModal();}
function field(label,name,value,attrs='',type='number'){return `<label class="field">${label}<input name="${name}" type="${type}" value="${escapeHtml(value)}" ${attrs}></label>`;}
function buttons(label='Salvar registro'){return `<div class="modal-actions"><button class="secondary-button" type="button" data-action="close">Cancelar</button><button class="primary-button" type="submit">${label}</button></div>`;}
function openMeal(){if(window.OasisUI?.openMeal)return window.OasisUI.openMeal();openManualMeal();}
function addMeal(meal){nutritionTab='diary';if(state.meals.length>=100)throw Error('Você já tem 100 alimentos neste dia. Exclua um registro antes de adicionar outro.');const id=Math.max(Date.now(),...state.meals.map(m=>m.id+1));state.meals.push({...meal,id});state.habits[0]=true;$('#modal').close();update('Alimento registrado no seu dia.');}
function openManualMeal(){modal('Registrar refeição','Adicione os valores da porção que você consumiu.',`<form data-form="meal">${field('O que você comeu?','name','','required maxlength="100" placeholder="Ex.: arroz, feijão e frango"','text')}<label class="field">Refeição<select name="type">${['Café da manhã','Almoço','Lanche da tarde','Jantar','Outra refeição'].map(x=>`<option>${x}</option>`).join('')}</select></label>${field('Calorias da porção (kcal)','kcal','','required min="0" max="10000" step="0.1" placeholder="Ex.: 450"')}<div class="form-grid">${field('Proteínas (g)','p','0','min="0" max="1000" step="0.1" required')}${field('Carboidratos (g)','c','0','min="0" max="1000" step="0.1" required')}${field('Gorduras (g)','f','0','min="0" max="1000" step="0.1" required')}</div>${buttons('Registrar refeição')}</form>`);}
function openWeight(){modal('Registrar peso','Se já houver um registro nesta data, ele será atualizado.',`<form data-form="weight">${field('Seu peso (kg)','value',state.weights.at(-1)?.value??'','required min="20" max="500" step="0.1"')}${field('Data do registro','date',dateKey(today),`required max="${dateKey(today)}" min="1900-01-01"`,'date')}${buttons('Registrar peso')}</form>`);}
function openSettings(){modal('Minhas metas','Ajuste as metas que você acompanha diariamente.',`<form data-form="settings">${field('Meta diária de calorias (kcal)','calorieGoal',state.calorieGoal,'required min="1" max="10000" step="1"')}${field('Meta diária de água (ml)','waterGoal',state.waterGoal,'required min="250" max="10000" step="50"')}${field('Meta de peso (kg)','goalWeight',state.personalPlan?.weightGoalPending?'':state.goalWeight,`${state.personalPlan?.weightGoalPending?'':'required'} min="20" max="500" step="0.1"`)}<label class="device-choice demo-setting"><input type="checkbox" name="save" ${saveOnDevice?'checked':''}><span>Guardar esta demonstração neste dispositivo.<br><small class="muted">Sem sincronização entre celulares ou computadores.</small></span></label>${buttons('Salvar ajustes')}</form><button class="reset-button demo-setting" data-action="reset">Restaurar dados de exemplo</button>`);}
function openCalculator(){modal('Calorias pelos macronutrientes','Informe os gramas dos nutrientes, e não o peso total do alimento.',`<form data-form="calculator"><div class="form-grid">${field('Proteínas (g)','protein',25,'required min="0" max="1000" step="0.1" data-calc')}${field('Carboidratos (g)','carbs',40,'required min="0" max="1000" step="0.1" data-calc')}${field('Gorduras (g)','fat',12,'required min="0" max="1000" step="0.1" data-calc')}</div><div class="calc-result" aria-live="polite"><span>Energia estimada da porção</span><strong id="calculated">368 kcal</strong><p>Proteínas × 4 + carboidratos × 4 + gorduras × 9. Uma estimativa simplificada; o valor no rótulo pode variar.</p></div><button type="button" data-action="close" class="primary-button full-width">Concluir</button></form>`);}
function sessionTime(){if(!state.startedAt)return '00:00';const seconds=Math.floor(((state.finishedAt||Date.now())-state.startedAt)/1000);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function addWater(amount=250){if(!Number.isInteger(amount)||amount<1||amount>1000)throw new Error('Informe uma quantidade de 1 a 1000 ml.');state.water+=amount;update(`+ ${amount} ml registrados. Um gole de cada vez.`);return {waterMl:state.water,goalMl:state.waterGoal};}
function action(name){if(name==='food-diary'||name==='food-plan'){nutritionTab=name==='food-plan'?'plan':'diary';render();return;}if(state.personalPlan?.training.status==='awaiting_assessment'&&['start-workout','finish-workout'].includes(name)){toast('Seu treino aguarda avaliação profissional.');return;}switch(name){case 'scroll-exercises':document.querySelector('.exercise')?.scrollIntoView({behavior:'smooth',block:'center'});break;case 'water':addWater();break;case 'meal':openMeal();break;case 'weight':openWeight();break;case 'settings':openSettings();break;case 'calculator':openCalculator();break;case 'close':$('#modal').close();break;case 'quick':modal('Um pequeno registro','O que você quer adicionar ao seu dia?',`<div class="quick-options"><button data-action="meal">${icon('utensils')}Refeição</button><button data-action="water-quick">${icon('droplet')}250 ml de água</button><button data-action="weight">${icon('weight')}Peso</button><button data-action="calculator">${icon('calculator')}Calcular calorias</button></div>`);break;case 'water-quick':$('#modal').close();addWater();break;case 'start-workout':state.workoutStarted=true;state.startedAt=Date.now();state.finishedAt=null;update('Sessão iniciada. Respeite seu ritmo.');break;case 'finish-workout':if(state.exercises.length!==6)return;state.workoutDone=true;state.finishedAt=Date.now();state.habits[2]=true;update('Treino concluído. Mais um dia de cuidado!');break;case 'reset':modal('Restaurar a demonstração?','Os registros que você alterou nesta demonstração serão substituídos pelos exemplos.',`<div class="modal-actions"><button class="secondary-button" data-action="close">Cancelar</button><button class="primary-button" data-action="confirm-reset">Restaurar exemplos</button></div>`);break;case 'confirm-reset':if(window.oasisSave)return;state=structuredClone(initialState);$('#modal').close();update('Demonstração restaurada.');break;}}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(button){if(button.disabled)return;if(button.dataset.view){navigate(button.dataset.view);return;}if(button.dataset.action){action(button.dataset.action);return;}if(button.dataset.habit!==undefined){const i=Number(button.dataset.habit);state.habits[i]=!state.habits[i];update();return;}if(button.dataset.exercise!==undefined){if(!state.workoutStarted)return;const i=Number(button.dataset.exercise);state.exercises=state.exercises.includes(i)?state.exercises.filter(x=>x!==i):[...state.exercises,i];if(state.workoutDone){state.workoutDone=false;state.finishedAt=null;state.habits[2]=false;}update();return;}if(button.dataset.removeMeal){state.meals=state.meals.filter(m=>m.id!==Number(button.dataset.removeMeal));update('Refeição removida da demonstração.');return;}}const brand=e.target.closest('.brand');if(brand){e.preventDefault();navigate('hoje');}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),kind=form.dataset.form;if(kind==='meal'){nutritionTab='diary';const name=String(data.get('name')).trim();if(!name){form.elements.name.setCustomValidity('Informe o nome da refeição.');form.elements.name.reportValidity();return;}state.meals.push({id:Date.now(),name,type:String(data.get('type')),kcal:Number(data.get('kcal')),p:Number(data.get('p')),c:Number(data.get('c')),f:Number(data.get('f'))});state.habits[0]=true;}else if(kind==='weight'){const record={date:String(data.get('date')),value:Number(data.get('value'))};state.weights=state.weights.filter(w=>w.date!==record.date);state.weights.push(record);state.weights.sort((a,b)=>a.date.localeCompare(b.date));}else if(kind==='settings'){state.calorieGoal=Number(data.get('calorieGoal'));state.waterGoal=Number(data.get('waterGoal'));if(data.get('goalWeight')){state.goalWeight=Number(data.get('goalWeight'));if(state.personalPlan)state.personalPlan.weightGoalPending=false;}if(state.personalPlan)state.personalPlan.nutrition.targetKcal=state.calorieGoal;saveOnDevice=data.get('save')==='on';if(!saveOnDevice){try{localStorage.removeItem('webfit-demo-v1');}catch{}}}else{return;}$('#modal').close();update(kind==='settings'?'Ajustes salvos.':kind==='weight'?'Peso registrado. Sua história continua.':'Refeição registrada no seu dia.');});
document.addEventListener('input',e=>{if(e.target.name==='name')e.target.setCustomValidity('');if(e.target.matches('[data-calc]')){const form=e.target.form;const p=Number(form.elements.protein.value),c=Number(form.elements.carbs.value),f=Number(form.elements.fat.value);$('#calculated').textContent=form.checkValidity()?`${fmt(p*4+c*4+f*9,1)} kcal`:'Revise os valores';}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
setInterval(()=>{const el=$('#session-time');if(el&&state.workoutStarted&&!state.workoutDone)el.textContent=sessionTime();},1000);
view=names[location.hash.slice(1)]?location.hash.slice(1):'hoje';render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'oasinsinc_add_water',title:'Registrar água no Oasis',description:'Registra água na demonstração e atualiza o painel visível.',inputSchema:{type:'object',properties:{amountMl:{type:'integer',minimum:1,maximum:1000}},required:['amountMl'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(window.oasisSave||document.body.classList.contains('app-locked'))throw new Error('Ferramenta disponível apenas na demonstração.');if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='amountMl'))throw new Error('Entrada inválida.');return addWater(input.amountMl);}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

window.OasisApp={render,navigate,toast,modal,field,buttons,icon,escapeHtml,addMeal,openManualMeal,getState:()=>structuredClone(state),load(value){state=structuredClone(value);render();},demo(){state=structuredClone(initialState);render();},getView:()=>view};
